ControlPropertyState.AutoRuleBindingString:
If(
    Self.SelectedButton.Label = "Agregar",
    If(
        IsBlank(Trim(TextInputCanvas1_1.Value)),
        Notify(
            "Debe agregar un numero de tula",
            NotificationType.Error
        ),
        If(
            !IsBlank(
                LookUp(
                    'CH-Tbl-Bags',
                    ReceptionID.ReceptionBatch.'CH-Tbl-ReceptionBatch' = FluentDetailsList2.Selected.ReceptionBatch.'CH-Tbl-ReceptionBatch' && BagID = Trim(TextInputCanvas1_1.Value)
                )
            ),
            Notify(
                "Este numero de tula ya se encuentra registrado en otra planilla en el mismo lote de recepcion",
                NotificationType.Error
            ),
            If(
                FluentDetailsList2.Selected.ReceptionBatch.ReceptionStatus = 'ReceptionStatus (CH-Tbl-ReceptionBatches)'.'En progreso',
                Patch(
                    'CH-Tbl-Bags',
                    Defaults('CH-Tbl-Bags'),
                    {
                        BagID: Trim(TextInputCanvas1_1.Value),
                        ReceptionID: FluentDetailsList2.Selected,
                        BagStatus: If(
                            FluentDetailsList2.Selected.ReceptionBatch.ReceptionStatus = 'ReceptionStatus (CH-Tbl-ReceptionBatches)'.'En boveda',
                            'BagStatus (CH-Tbl-Bags)'.'Almacenada en boveda',
                            'BagStatus (CH-Tbl-Bags)'.'Recibida en exclusa'
                        ),
                        Name: Trim(TextInputCanvas1_1.Value)
                    }
                );
                Reset(TextInputCanvas1_1);
                UpdateContext({varShowNewTula: false}),
                Patch(
                    'CH-Tbl-ApprovalRequests',
                    Defaults('CH-Tbl-ApprovalRequests'),
                    {
                        RequestType: "Agregar tula",
                        RequestDetails: Concatenate(
                            "Lote de recepcion ",
                            FluentDetailsList2.Selected.ReceptionBatch.Name,
                            Char(10),
                            "Agregar tula ",
                            Trim(TextInputCanvas1_1.Value),
                            " a la planilla ",
                            FluentDetailsList2.Selected.ReceiptID
                        ),
                        RequestResources: "{" & Concatenate(
                            """",
                            "ReceiptGUID",
                            """",
                            ":",
                            """",
                            FluentDetailsList2.Selected.'CH-Tbl-Receptions',
                            """"
                        ) & Concatenate(
                            ",",
                            """",
                            "BagID",
                            """",
                            ":",
                            """",
                            Trim(TextInputCanvas1_1.Value),
                            """"
                        ) & Concatenate(
                            ",",
                            """",
                            "ReceptionBatchGUID",
                            """",
                            ":",
                            """",
                            FluentDetailsList2.Selected.ReceptionBatch.'CH-Tbl-ReceptionBatch',
                            """"
                        ) & "}"
                    }
                );
                Notify(
                    "Se creo una gestion de aprobacion para agregar la tula a la planilla",
                    NotificationType.Information
                );
                Patch(
                    'CH-Tbl-Bags',
                    FluentDetailsList3.Selected,
                    {BagStatus: 'BagStatus (CH-Tbl-Bags)'.'Pendiente de revision por supervisor - exclusa'}
                );
            );
            Reset(TextInputCanvas1_1);
            UpdateContext({varShowNewTula: false});
            Refresh('CH-Tbl-Bags');
        )
    )
);
If(
    Self.SelectedButton.Label = "Cancelar",
    UpdateContext({varShowNewTula: false})
);

If(
    Self.SelectedButton.Label = "Agregar",
