            NotificationType.Error
        ),
        If(
            !IsBlank(
                LookUp(
                    'CH-Tbl-Bags',
                    ReceptionID.ReceptionBatch.'CH-Tbl-ReceptionBatch' = FluentDetailsList2.Selected.ReceptionBatch.'CH-Tbl-ReceptionBatch' && BagID = Trim(TextInputCanvas1_2.Value)
                )
            ),
            Notify(
                "Este numero de tula ya se encuentra registrado en otra planilla en el mismo lote de recepcion",
