                            'BagStatus (CH-Tbl-Bags)'.'Recibida en exclusa'
                        ),
                        Name: Trim(TextInputCanvas1_2.Value)
                    }
                );
                Reset(TextInputCanvas1_2);
                UpdateContext({varShowNewTula: false}),
                Patch(
