                    {
                        RequestType: "Agregar tula",
                        RequestDetails: Concatenate(
                            "<p>",
                            "Lote de recepcion ",
                            FluentDetailsList2.Selected.ReceptionBatch.Name,
                            "<br>",
                            "Agregar tula ",
                            Trim(TextInputCanvas1_2.Value),
                            " a la planilla ",
                            FluentDetailsList2.Selected.ReceiptID,
                            "</p>"
                        ),
                        RequestResources: "{" & Concatenate(
                            """",
                            "ReceiptGUID",
                            """",
                            ":",
                            """",
                            FluentDetailsList2.Selected.'CH-Tbl-Receptions',
                            """"
                        ) & Concatenate(
                            ",",
                            """",
                            "BagID",
                            """",
                            ":",
                            """",
                            Trim(TextInputCanvas1_2.Value),
                            """"
                        ) & Concatenate(
                            ",",
                            """",
                            "ReceptionBatchGUID",
                            """",
                            ":",
                            """",
                            FluentDetailsList2.Selected.ReceptionBatch.'CH-Tbl-ReceptionBatch',
                            """"
                        ) & "}"
                    }
                );
                Notify(
                    "Se creo una gestion de aprobacion para agregar la tula a la planilla",
                    NotificationType.Information
                );
                Patch(
                    'CH-Tbl-Bags',
                    FluentDetailsList3.Selected,
                    {BagStatus: 'BagStatus (CH-Tbl-Bags)'.'Pendiente de revision por supervisor - exclusa'}
                );
            );
            Reset(TextInputCanvas1_2);
            UpdateContext({varShowNewTula: false});
            Refresh('CH-Tbl-Bags');
        )
    )
);
If(
    Self.SelectedButton.Label = "Cancelar",
    UpdateContext({varShowNewTula: false})
);

